  jsonb_set(good,'{contract_version}','null'::jsonb),
  jsonb_set(good,'{decisions,0,verdict}','null'::jsonb),
  jsonb_set(good,'{decisions,0,citations,0,role}','null'::jsonb),
  jsonb_set(good,'{decisions,0,citations}','[]'::jsonb),
  jsonb_set(good,'{decisions}','[]'::jsonb))) LOOP
  BEGIN
   PERFORM signal_interest_decision_derive_decisions_v2(r,provider,bad);
   RAISE EXCEPTION 'forged/cross-root/missing decision accepted';
  EXCEPTION WHEN sqlstate '23514' THEN NULL;END;
 END LOOP;
 -- Build a ledger-shaped fixture under replication mode so unrelated source,
 -- registration and policy setup are not forged as a real paid admission.
 PERFORM set_config('session_replication_role','replica',true);
 INSERT INTO organizations(id,slug,legal_name,status)
 VALUES(org_id,'interest-v2-pg-fixture','Interest V2 PG Fixture','active');
 INSERT INTO signal_processing_admissions(id,organization_id,workspace_id,brand_id,actor_user_id,
  policy_version_id,action,target_id,idempotency_key,request_digest,provider,model,configuration,
  configuration_digest,execution_cap_micro_usd,budget_date,budget_timezone,admission_not_after,automatic,receipt_digest)
 VALUES(admission_id,org_id,(r->>'workspace_id')::uuid,gen_random_uuid(),actor_id,gen_random_uuid(),
  'interest_decision',owner_id,'interest-v2-pg-fixture',signal_semantic_context_digest_v1('admission'),
  'anthropic','claude-sonnet-4-6',signal_interest_decision_configuration_v2(),
  signal_semantic_context_digest_json_v2(signal_interest_decision_configuration_v2()),1000000,
  current_date,'UTC',clock_timestamp()+interval '1 day',true,signal_semantic_context_digest_v1('receipt'));
 INSERT INTO signal_interest_decision_owners_v1(id,workspace_id,organization_id,actor_user_id,
  generation_id,source_execution_id,taxonomy_term_id,term_key,definition_digest,
  source_input_digest,source_input_revision,source_context_digest,processing_admission_id,
  hard_cap_micro_usd,expected_roots,manifest_roots,manifest_complete,status,provider_contract_version)
 VALUES(owner_id,(r->>'workspace_id')::uuid,org_id,actor_id,gen_random_uuid(),gen_random_uuid(),
  (r->'interest'->>'taxonomy_term_id')::uuid,r->'interest'->>'term_key',r->'interest'->>'definition_digest',
  signal_semantic_context_digest_v1('source'),1,r->>'context_digest',admission_id,
  1000000,2,2,true,'ready',2);
 INSERT INTO signal_interest_decision_pages_v1(id,owner_id,page_index,root_count,first_root_id,last_root_id,
  manifest,manifest_body,page_body,manifest_digest)
 VALUES(page_id,owner_id,0,2,(r->'roots'->0->>'root_id')::uuid,(r->'roots'->1->>'root_id')::uuid,
  f->'manifest',(f->'manifest')::text,(r-'request_digest')::text,f->'manifest'->>'manifest_digest');
 INSERT INTO signal_interest_decision_requests_v1(id,owner_id,page_id,request_index,custom_id,
  request,request_body,request_digest,interest_identity_digest,provider_request,provider_body,
  provider_request_digest,reserved_micro_usd,provider_contract_version,provider_core_body_v2)
 VALUES(request_id,owner_id,page_id,0,provider->>'custom_id',r,f->>'request_body',r->>'request_digest',
  signal_semantic_context_digest_json_v2(r->'interest'),provider,f->>'provider_body',
  f->'req'->>'provider_request_digest',500000,2,f->>'provider_core_body');
 FOR root IN SELECT value FROM jsonb_array_elements(r->'roots') LOOP
  INSERT INTO signal_interest_decision_request_roots_v1(owner_id,request_id,root_id,
   root_fingerprint,asset_sha256,correction_digest,root_body)
  VALUES(owner_id,request_id,(root->>'root_id')::uuid,root->>'fingerprint',root->>'asset_sha256',
   root->>'correction_digest',root);
 END LOOP;
 INSERT INTO signal_interest_decision_batches_v1(id,owner_id,page_id,admission_id,submission_key,
  state,provider_batch_id,manifest_body,manifest_digest)
 VALUES(batch_id,owner_id,page_id,admission_id,'interest-v2-pg-batch','ended','msgbatch_local_v2',
  (f->'manifest')::text,signal_semantic_context_digest_json_v2(f->'manifest'));
 INSERT INTO signal_interest_decision_calls_v1(id,owner_id,request_id,batch_id,attempt_index,
  organization_id,status,reserved_micro_usd,observed_micro_usd,settled_micro_usd,
  budget_date,budget_timezone,raw_body,raw_sha256,output_text,output_digest,outcome,settled_at)
 VALUES(test_call_id,owner_id,request_id,batch_id,1,org_id,'settled',500000,500,500,current_date,'UTC',
  f->>'raw_body',f->>'raw_sha256',f->>'output_text',f->>'output_digest','succeeded',clock_timestamp());
 PERFORM set_config('session_replication_role','origin',true);
 BEGIN
  UPDATE signal_interest_decision_calls_v1 SET validation_status='invalid_output' WHERE id=test_call_id;
  RAISE EXCEPTION 'V1-style update consumed V2 receipt';
 EXCEPTION WHEN sqlstate '23514' THEN NULL;END;
 result:=apply_signal_interest_decision_item_v2(test_call_id);
 IF result->>'validation_status'<>'accepted' OR (result->>'root_count')::integer<>2
  OR (SELECT count(*) FROM signal_interest_decision_root_evidence_v1 WHERE call_id=test_call_id)<>2
  OR (SELECT count(*) FROM signal_interest_decision_root_evidence_v1 WHERE call_id=test_call_id
   AND output_digest=f->>'output_digest')<>2
  OR (SELECT raw_body FROM signal_interest_decision_calls_v1 WHERE id=test_call_id) IS DISTINCT FROM f->>'raw_body'
 THEN RAISE EXCEPTION 'V2 raw evidence receipt failed';END IF;
 result:=apply_signal_interest_decision_item_v2(test_call_id);
 IF result->>'replayed'<>'true' OR (SELECT count(*) FROM signal_interest_decision_root_evidence_v1 WHERE call_id=test_call_id)<>2
 THEN RAISE EXCEPTION 'V2 replay mutated evidence';END IF;
 -- Unknown provider cannot inherit the paid V1 model authority.
 prior_provider:=provider;prior_provider_body:=f->>'provider_body';
 PERFORM set_config('session_replication_role','replica',true);
 UPDATE signal_interest_decision_requests_v1 SET provider_request=jsonb_set(provider,
  '{params,model}','"unknown-model"'::jsonb),provider_body=jsonb_set(provider,
  '{params,model}','"unknown-model"'::jsonb)::text WHERE id=request_id;
 PERFORM set_config('session_replication_role','origin',true);
 BEGIN
  PERFORM apply_signal_interest_decision_item_v2(test_call_id);
  RAISE EXCEPTION 'unknown provider applied';
 EXCEPTION WHEN sqlstate '23514' THEN NULL;END;
 PERFORM set_config('session_replication_role','replica',true);
 UPDATE signal_interest_decision_requests_v1 SET provider_request=prior_provider,
  provider_body=prior_provider_body WHERE id=request_id;
 -- A second settled raw receipt with malformed ordinal keeps bytes and settles
 -- to invalid_output; no normalized evidence is written.
 INSERT INTO signal_interest_decision_batches_v1(id,owner_id,page_id,admission_id,submission_key,
  state,provider_batch_id,manifest_body,manifest_digest)
 VALUES(batch2_id,owner_id,page_id,admission_id,'interest-v2-pg-batch2','ended','msgbatch_local_v2_2',
  (f->'manifest')::text,signal_semantic_context_digest_json_v2(f->'manifest'));
 bad:=jsonb_set(good,'{decisions,0,root_ordinal}','999999999999999999999999'::jsonb);
 output2:=bad::text;
 raw2:=jsonb_set((f->>'raw_body')::jsonb,'{result,message,content,0,text}',to_jsonb(output2))::text;
 INSERT INTO signal_interest_decision_calls_v1(id,owner_id,request_id,batch_id,retry_of_call_id,attempt_index,
  organization_id,status,reserved_micro_usd,observed_micro_usd,settled_micro_usd,
  budget_date,budget_timezone,raw_body,raw_sha256,output_text,output_digest,outcome,settled_at)
 VALUES(call2_id,owner_id,request_id,batch2_id,test_call_id,2,org_id,'settled',500000,500,500,current_date,'UTC',
  raw2,signal_semantic_context_digest_v1(raw2),output2,signal_semantic_context_digest_v1(output2),
  'succeeded',clock_timestamp());
 PERFORM set_config('session_replication_role','origin',true);
 result:=apply_signal_interest_decision_item_v2(call2_id);
 IF result->>'validation_status'<>'invalid_output'
  OR (SELECT raw_body FROM signal_interest_decision_calls_v1 WHERE id=call2_id) IS DISTINCT FROM raw2
  OR EXISTS(SELECT 1 FROM signal_interest_decision_root_evidence_v1 WHERE call_id=call2_id)
 THEN RAISE EXCEPTION 'malformed provider output lost receipt or produced evidence';END IF;
END $test$;
ROLLBACK;
